import json, os, sys, numpy as np
from scipy import stats
from statsmodels.tsa.stattools import adfuller

N_PERM = 5000
ALPHA_SIG = 0.05
CANARIES = ["token_entropy", "ece"]
DOWNSTREAMS = ["distinct_1", "distinct_2", "distinct_3", "mauve"]
HIGHER_IS_WORSE = {"ece", "perplexity"}
LOWER_IS_WORSE = {"token_entropy", "distinct_1", "distinct_2", "distinct_3", "mauve"}

sys.path.insert(0, "/root/autodl-tmp/distrib_canary_collapse")
from permutation_granger import permutation_granger_test

def load_series(data_dir):
    path = os.path.join(data_dir, "all_metrics.json")
    with open(path) as f:
        data = json.load(f)
    data.sort(key=lambda x: x["generation"])
    out = {}
    for k in CANARIES + DOWNSTREAMS:
        out[k] = np.array([d[k] for d in data], dtype=float)
    return out, len(data)

def orient(series, name):
    return -series.copy() if name in LOWER_IS_WORSE else series.copy()

def bh_fdr(p_values, alpha=0.05):
    pv = np.array(p_values, dtype=float)
    n = len(pv)
    valid = ~np.isnan(pv)
    adjusted = np.full(n, np.nan)
    if valid.sum() == 0:
        return adjusted.tolist(), [False] * n
    idx = np.where(valid)[0]
    p_valid = pv[idx]
    sorted_idx = np.argsort(p_valid)
    ranks = np.empty_like(sorted_idx)
    ranks[sorted_idx] = np.arange(1, len(p_valid) + 1)
    m = len(p_valid)
    adj = p_valid * m / ranks
    adj_sorted = adj[sorted_idx].copy()
    for i in range(m - 2, -1, -1):
        adj_sorted[i] = min(adj_sorted[i], adj_sorted[i + 1])
    adj_sorted = np.minimum(adj_sorted, 1.0)
    adj_final = np.empty(m)
    adj_final[sorted_idx] = adj_sorted
    for i, ix in enumerate(idx):
        adjusted[ix] = adj_final[i]
    significant = [(adjusted[i] < alpha if not np.isnan(adjusted[i]) else False) for i in range(n)]
    return adjusted.tolist(), significant

def naive_xcorr(c, d, cn, dn, max_lag=5):
    x, y = orient(c, cn), orient(d, dn)
    n = len(x)
    best_lag, best_r, best_p = 0, 0.0, 1.0
    for lag in range(-max_lag, max_lag + 1):
        if lag >= 0:
            a, b = x[lag:], y[:n - lag]
        else:
            a, b = x[:n + lag], y[-lag:]
        if len(a) < 4 or np.std(a) < 1e-12 or np.std(b) < 1e-12:
            continue
        r, p = stats.pearsonr(a, b)
        if abs(r) > abs(best_r):
            best_lag, best_r, best_p = lag, r, p
    return {"method": "naive_xcorr", "peak_lag": int(best_lag), "r": round(float(best_r), 4),
            "p_value": round(float(best_p), 6), "significant": bool(best_p < ALPHA_SIG)}

def diff_xcorr(c, d, cn, dn, max_lag=5):
    dx, dy = np.diff(orient(c, cn)), np.diff(orient(d, dn))
    n = len(dx)
    best_lag, best_r, best_p = 0, 0.0, 1.0
    for lag in range(-max_lag, max_lag + 1):
        if lag >= 0:
            a, b = dx[lag:], dy[:n - lag]
        else:
            a, b = dx[:n + lag], dy[-lag:]
        if len(a) < 4 or np.std(a) < 1e-12 or np.std(b) < 1e-12:
            continue
        r, p = stats.pearsonr(a, b)
        if abs(r) > abs(best_r):
            best_lag, best_r, best_p = lag, r, p
    return {"method": "diff_xcorr", "peak_lag": int(best_lag), "r": round(float(best_r), 4),
            "p_value": round(float(best_p), 6), "significant": bool(best_p < ALPHA_SIG)}

def threshold_onset(c, d, cn, dn, sigma_mult=3):
    x, y = orient(c, cn), orient(d, dn)
    def find_onset(s):
        d = np.diff(s)
        if len(d) == 0 or np.std(d) < 1e-12:
            return None
        threshold = sigma_mult * np.std(d)
        for i, v in enumerate(d):
            if abs(v) > threshold:
                return i + 1
        return None
    oc, od = find_onset(x), find_onset(y)
    lead = (od - oc) if (oc is not None and od is not None) else (10 if oc is not None else None)
    return {"method": "threshold_onset", "onset_canary": oc, "onset_downstream": od,
            "lead_time": lead, "significant": bool(lead is not None and lead > 0)}

def perm_granger(c, d, cn, dn, direction="forward"):
    x, y = orient(c, cn), orient(d, dn)
    if direction == "forward":
        result = permutation_granger_test(x, y, max_lag=1, n_perm=N_PERM)
    else:
        result = permutation_granger_test(y, x, max_lag=1, n_perm=N_PERM)
    return {"method": "perm_granger", "f_stat": round(float(result["f_stat"]), 4),
            "p_value": round(float(result["p_value"]), 6),
            "significant": bool(result["p_value"] < ALPHA_SIG), "direction": direction}

def ty_granger(c, d, cn, dn):
    x, y = orient(c, cn), orient(d, dn)
    try:
        adf_x = adfuller(x, maxlag=2)
        adf_y = adfuller(y, maxlag=2)
        d_x = 0 if adf_x[1] < 0.05 else 1
        d_y = 0 if adf_y[1] < 0.05 else 1
        d_max = max(d_x, d_y)
        from statsmodels.tsa.api import VAR
        dd = np.column_stack([x, y])
        model = VAR(dd)
        k = 1
        total_lag = k + d_max
        if total_lag >= len(x) - 2:
            return {"method": "ty_granger", "chi2": 0, "p_value": 1.0, "d_max": d_max, "df_resid": 0, "significant": False}
        fitted = model.fit(total_lag)
        df_resid = fitted.nobs - fitted.k_ar * 2 - 1
        test = fitted.test_causality("y1", "y2", kind="wald")
        chi2 = float(test.test_statistic)
        pval = float(test.pvalue)
        return {"method": "ty_granger", "chi2": round(chi2, 4), "p_value": round(pval, 6),
                "d_max": d_max, "df_resid": max(0, df_resid), "significant": bool(pval < ALPHA_SIG)}
    except Exception as e:
        return {"method": "ty_granger", "chi2": 0, "p_value": 1.0, "d_max": -1, "df_resid": 0, "significant": False, "error": str(e)}

def clean(obj):
    if isinstance(obj, (np.floating, np.float64)):
        return float(obj)
    if isinstance(obj, (np.integer,)):
        return int(obj)
    if isinstance(obj, np.bool_):
        return bool(obj)
    if isinstance(obj, dict):
        return {k: clean(v) for k, v in obj.items()}
    if isinstance(obj, list):
        return [clean(v) for v in obj]
    return obj

base = "/root/autodl-tmp/distrib_canary_collapse/results/alpha_sweep"
for seed_name in ["a000_s42", "a000_s43", "a000_s44"]:
    exp_dir = os.path.join(base, seed_name)
    series, n_gens = load_series(exp_dir)
    print(f"Processing {seed_name} ({n_gens} gens)...")

    pairs_out = []
    pg_fwd_p, pg_rev_p, diff_p = [], [], []
    for cn in CANARIES:
        for dn in DOWNSTREAMS:
            c, d = series[cn], series[dn]
            r_naive = naive_xcorr(c, d, cn, dn)
            r_diff = diff_xcorr(c, d, cn, dn)
            r_thresh = threshold_onset(c, d, cn, dn)
            r_pg_fwd = perm_granger(c, d, cn, dn, "forward")
            r_pg_rev = perm_granger(c, d, cn, dn, "reverse")
            r_ty = ty_granger(c, d, cn, dn)
            pg_fwd_p.append(r_pg_fwd["p_value"])
            pg_rev_p.append(r_pg_rev["p_value"])
            diff_p.append(r_diff["p_value"])
            pairs_out.append({
                "canary": cn, "downstream": dn,
                "forward": {
                    "naive_xcorr": r_naive, "diff_xcorr": r_diff,
                    "threshold_onset": r_thresh, "perm_granger": r_pg_fwd,
                    "ty_granger": r_ty
                },
                "reverse": {"perm_granger": r_pg_rev}
            })

    # BH FDR
    pg_fwd_adj, pg_fwd_sig = bh_fdr(pg_fwd_p)
    pg_rev_adj, pg_rev_sig = bh_fdr(pg_rev_p)
    diff_adj, diff_sig = bh_fdr(diff_p)
    for i, p in enumerate(pairs_out):
        p["forward"]["perm_granger"]["p_fdr"] = pg_fwd_adj[i]
        p["forward"]["perm_granger"]["significant_fdr"] = pg_fwd_sig[i]
        p["reverse"]["perm_granger"]["p_fdr"] = pg_rev_adj[i]
        p["reverse"]["perm_granger"]["significant_fdr"] = pg_rev_sig[i]
        p["forward"]["diff_xcorr"]["p_fdr"] = diff_adj[i]
        p["forward"]["diff_xcorr"]["significant_fdr"] = diff_sig[i]

    output = {
        "n_generations": n_gens,
        "data_dir": exp_dir,
        "methods": ["naive_xcorr", "diff_xcorr", "threshold_onset", "perm_granger", "ty_granger"],
        "pairs": pairs_out,
    }
    analysis_dir = os.path.join(exp_dir, "analysis_mauve")
    os.makedirs(analysis_dir, exist_ok=True)
    out_path = os.path.join(analysis_dir, "5method_leadlag.json")
    with open(out_path, "w") as f:
        json.dump(clean(output), f, indent=2)
    print(f"  Saved: {out_path}")
